def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    utilization = 1.0 - (remaining / bins)
    target = 0.75
    score = -np.exp((utilization - target) ** 2)
    return np.where(valid, score, -np.inf)

